static void ld047rf1l01_init(void)
{
    int i;
    struct dsi_cmd_packet ld047rf1l01_display_on = {0x05, 0x29, 0x00};

    for (i = 0; i < ARRAY_SIZE(fitipower_ld047rf1l01_cmd_list); i++)
        dsi_write_cmd(&fitipower_ld047rf1l01_cmd_list[i]);

    msleep(120);
    dsi_write_cmd(&ld047rf1l01_display_on);
    msleep(20);
}

static inline int m_gpio_request(int gpio, const char *name)
{
    if (gpio < 0)
        return 0;

    int ret = gpio_request(gpio, name);
    if (ret) {
        char buf[20];
        printk(KERN_ERR "ld047rf1l01: failed to request %s: %s\n", name, gpio_to_str(gpio, buf));
        return ret;
    }

    return 0;
}

static inline void m_gpio_free(int gpio)
{
    if (gpio >= 0)
        gpio_free(gpio);
}

static inline void m_gpio_direction_output(int gpio, int value)
{
    if (gpio >= 0)
        gpio_direction_output(gpio, value);
}

static inline void m_gpio_direction_input(int gpio)
{
    if (gpio >= 0)
        gpio_direction_input(gpio);
}

static int ld047rf1l01_power_on(struct lcdc *lcdc)
{
    if (ld047rf1l01_regulator)
        regulator_enable(ld047rf1l01_regulator);

    m_gpio_direction_output(gpio_lcd_power_en, 1);
    msleep(10);

    m_gpio_direction_output(gpio_lcd_rst, 1);
    m_gpio_direction_output(gpio_lcd_rst, 0);
    msleep(120);
    m_gpio_direction_output(gpio_lcd_rst, 1);
    msleep(10);

    m_gpio_direction_output(gpio_lcd_backlight_en, 1);

    return 0;
}

static int ld047rf1l01_power_off(struct lcdc *lcdc)
{
    if (ld047rf1l01_regulator)
        regulator_disable(ld047rf1l01_regulator);

    m_gpio_direction_output(gpio_lcd_backlight_en, 0);
    m_gpio_direction_output(gpio_lcd_rst, 0);
    m_gpio_direction_output(gpio_lcd_power_en, 0);

    return 0;
}

